// Where a RETIRED rail Workspace sends a user who was last on it.
//
// `activeWorkspace` is persisted, so removing a Workspace strands anyone whose last session ended
// there: they reopen the app pointed at a key the shell can no longer render. Every removal therefore
// owes a redirect, and this is the one place they live.
//
// Extracted from the `onRehydrateStorage` closure in `store/index.ts` (skills-move-to-teams-and-pair-
// with-personas). Inline, they could not be tested — which is why `design`, `algorithms` and `agents`
// had shipped without a single assertion between them, each one a silent landing-on-nothing away from
// a bug nobody would attribute to a rehydrate. Pulling them into a pure function costs one export and
// makes the whole set provable at once.
//
// PAGE-MODE migrations (`org` → `teams`, `design` → `designs`, …) deliberately stay in `index.ts`:
// those rename a tab WITHIN a surviving Workspace, which is a different failure (a wrong tab, not a
// blank screen) and they do not compose with these.

/** The subset of persisted state a workspace redirect reads and writes. */
export interface RetiredWorkspaceState {
  activeWorkspace?: string;
  projectsPageMode?: string;
  settingsSection?: string;
}

/**
 * Retired Workspace → where it went.
 *
 * `settingsSection` is set only when the destination is a specific Settings page — today just GitHub,
 * whose integration survives there. It replaced a `page` field that pointed at Planner TABS; every one
 * of those redirects was reversed when the graphs became rail Workspaces
 * (`five-graphs-become-rail-workspaces`), leaving the field unused, and an unused field that still
 * writes to `projectsPageMode` is a trap for the next person who reaches for it.
 */
const RETIRED: Record<string, { workspace: string; settingsSection?: string }> = {
  // Design Studio → the COMPONENTS workspace (`five-graphs-become-rail-workspaces`). It was retired
  // INTO the Planner as the "designs" tab (#move-to-planner); that tab is gone and the graph is a rail
  // destination again, so this redirect is REVERSED, not extended. Left pointing at projects/designs
  // it would now land on a page that does not exist — the exact blank screen this table prevents.
  design: { workspace: "components" },
  // `algorithms` IS NOT LISTED ANY MORE, and its absence is the point. It is a LIVE workspace again,
  // and this table must never redirect a key that still renders — `migrateRetiredWorkspace` would
  // "helpfully" move someone off a working screen. A live key belongs in `registry.ts`, not here.
  // Skills → the TEAMS workspace (skills-move-to-teams-and-pair-with-personas, then here). A skill is
  // injectable agent CONTEXT, so its home is beside the personas that carry it — that reasoning is
  // unchanged; only Teams' address is.
  skills: { workspace: "teams" },
  // Security -> LOGS (the-logs-workspace-scaffold-and-activity). Three of its four tabs were deleted
  // and the survivor, Activity, is an audit FEED -- history, which is what the Logs workspace is for.
  security: { workspace: "logs" },
  // "agents" was a pure rename to "security" (#2702), and security has since become logs. It points at
  // the FINAL destination rather than chaining: `migrateRetiredWorkspace` runs ONCE, so a redirect to
  // another retired key would land the user on a workspace the shell can no longer render -- the exact
  // blank screen this table exists to prevent.
  agents: { workspace: "logs" },
  // MCP -> the TEAMS page (mcp-moves-to-teams). An MCP server is injectable agent CAPABILITY, the
  // same class of thing as a skill, so it is READ beside the agents that get it rather than owning
  // a rail destination. Same destination as `skills`, and for the same reason.
  mcp: { workspace: "teams" },
  // Automations -> the TEAMS page (hooks-and-schedules-belong-to-the-persona). Its config is
  // carried by the persona now; its history is Logs -> Automations. Teams is where the thing it
  // used to edit lives, so that is where someone last on it should land.
  automation: { workspace: "teams" },
  // GitHub -> SETTINGS → GitHub (delete-the-github-screen-keep-the-integration). The screen was charts
  // over the API; it is gone. The INTEGRATION is not — publish and readiness still run on it — and the
  // one GitHub surface a user still touches is connecting an account, which lives in Settings. So the
  // redirect carries a SECTION, the only entry here that does: landing on Settings' General page would
  // be technically live and practically useless to someone who was looking at GitHub.
  github: { workspace: "settings", settingsSection: "github" },
  // The PLANNER -> GLANCE (delete-the-planner-ui-keep-the-planner). Its screen was the pitch-to-plan
  // conversation; planning is the director's job now. Glance is where projects are SEEN — its network
  // page is the project graph — so someone last on the Planner lands on the surface that still shows
  // what they were looking at, rather than on a workspace picked for being alive.
  projects: { workspace: "glance" },
  // The USE layer -> CONSOLE (network-sessions-live-in-the-console-screen). The separate Use rail
  // destination was removed; per-network sessions live in the Console workspace now. Console is a LIVE
  // workspace, which this table normally may not target — the exception holds because "use" itself no
  // longer renders, so this is a retire, not a redirect between two live screens.
  use: { workspace: "console" },
};

/**
 * A Planner PAGE that became a rail Workspace → the Workspace it became.
 *
 * Separate from {@link RETIRED} because it fixes a different failure. That table rewrites an
 * `activeWorkspace` naming a workspace the shell can no longer render — a blank screen, which someone
 * would report. This one rewrites a `projectsPageMode` naming a Planner tab that no longer exists: the
 * workspace still renders and the Planner just falls back to Projects, so a user who left on
 * Components silently reopens on Projects. Nothing errors, so nothing would ever be filed — which is
 * exactly why it needs a migration instead of being left to the fallback.
 */
const GRAPH_PAGES: Record<string, string> = {
  // NOT identity: the tab id was the internal feature name while the LABEL was "Components" (#2818),
  // and the Workspace takes the label.
  designs: "components",
  teams: "teams",
  algorithms: "algorithms",
  sounds: "sounds",
  data: "data",
};

/**
 * Rewrite a persisted `activeWorkspace` that names a Workspace which no longer exists.
 *
 * Mutates in place and returns the same object, matching how `onRehydrateStorage` hands state around.
 * A state that names a LIVE workspace — or none at all — is left exactly as it is: this must never
 * "helpfully" redirect someone away from a screen that still works.
 */
export function migrateRetiredWorkspace<T extends RetiredWorkspaceState>(state: T | null | undefined): T | null | undefined {
  if (!state) return state;
  const moved = RETIRED[state.activeWorkspace ?? ""];
  if (!moved) return state;
  state.activeWorkspace = moved.workspace;
  if (moved.settingsSection) state.settingsSection = moved.settingsSection;
  return state;
}

/**
 * Forward someone who was last on a Planner PAGE that is now its own Workspace.
 *
 * Only applies when `activeWorkspace` is `projects`: that workspace still exists, so
 * {@link migrateRetiredWorkspace} leaves it alone and this is the only thing that can catch it. A page
 * that is still a real Planner tab (`projects`) is untouched.
 *
 * `projectsPageMode` is reset to `projects` rather than left naming a departed tab — otherwise a later
 * Planner visit reopens on a page the tab strip no longer offers.
 */
export function migrateGraphPage<T extends RetiredWorkspaceState>(state: T | null | undefined): T | null | undefined {
  if (!state) return state;
  if ((state.activeWorkspace ?? "") !== "projects") return state;
  const moved = GRAPH_PAGES[state.projectsPageMode ?? ""];
  if (!moved) return state;
  state.activeWorkspace = moved;
  state.projectsPageMode = "projects";
  return state;
}

/** The retired keys, for tests and for anything that wants to report what was dropped. */
export const RETIRED_WORKSPACE_KEYS = Object.keys(RETIRED);

/** The Planner page ids that became Workspaces, for tests and for anything reporting the move. */
export const GRAPH_PAGE_KEYS = Object.keys(GRAPH_PAGES);
